head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_etn.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용

scwin.vScrenID = "ULDSTF08011.xml";
scwin.fr_SecuGrpId = SECUGRP_ID_EN; // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 법인선택팝업에서 fr_SecuGrpId 변수를 참조. 
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.clickBzProcsNo = "";
scwin.readOnlyYn = "N";
scwin.procJob = "";
scwin.logicPackYn = "Y";
scwin.vListInit = true;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 함수
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_ISU_NM); // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_KOR_NM);
        vIsurCd = arrPar[0].ISUR_CD;
    }
};
scwin.fn_set_code = function() {
    dts_EtnInst.DataID = "/CodeAction.do?method=listWrntCd&For=R";
    dts_EtnInst.Reset();
    //alert("call");

};



/**
 * 신규/추가상장의 목록검색시작일과 종료일자의 초기값 설정
 */
scwin.fn_initSearchDate = function(edtSDate, edtEDate) {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edtSDate.setValue('19000101');
    edtEDate.setValue($c.ut.cGetPlusDate2(vCurDate, 60));
};


/**
 * 추가상장신청시의 업무구분코드 가져오기
 */
scwin.fn_getListBzTpCd = function(str) {
    var val = '';
    if (str == LIST_BZ_TP_CD_002) {
        val = LIST_BZ_TP_CD_004;
    } else if (str == LIST_BZ_TP_CD_003) {
        val = LIST_BZ_TP_CD_005;
    }
    return val;
};
scwin.fn_list_sync = function() {
    scwin.vListInit = false;
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        var url = "/etn/EtnNewList.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listEtnReceipt&inputMessageId=ETN_NEWLISTING_SEARCH_OUT";
        url += "&ISUR_CD=" + $c.stf.getObjectValue(cmb_ISUR_CD);
        url += "&ISU_CD=" + $c.stf.getObjectValue(txb_ISU_CD);
        url += "&S_DATE=" + $c.stf.getObjectValue(edt_SDate);
        url += "&E_DATE=" + $c.stf.getObjectValue(edt_EDate);
        dts_List_1.DataID = encodeURI(url);
        dts_List_1.Reset();
        $c.cm.ShowWin(grd_List_1);
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        var url = "/etn/EtnNewList.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listEtnAddReceipt&inputMessageId=ETN_NEWLISTING_SEARCH_OUT";
        url += "&ISUR_CD=" + $c.stf.getObjectValue(cmb_ISUR_CD);
        url += "&ISU_CD=" + $c.stf.getObjectValue(txb_ISU_CD);
        url += "&S_DATE=" + $c.stf.getObjectValue(edt_SDate);
        url += "&E_DATE=" + $c.stf.getObjectValue(edt_EDate);
        dts_List_2.DataID = encodeURI(url);
        dts_List_2.Reset();
        $c.cm.ShowWin(grd_List_2);
    } else if (MaxTab_01.getSelectedTabIndex() == 3) {
        var url = "/etn/EtnNewList.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listEtnlosslmtReceipt&inputMessageId=ETN_NEWLISTING_LOSSLMT_SEARCH_OUT";
        url += "&ISUR_CD=" + $c.stf.getObjectValue(cmb_ISUR_CD);
        url += "&ISU_CD=" + $c.stf.getObjectValue(txb_ISU_CD);
        url += "&S_DATE=" + $c.stf.getObjectValue(edt_SDate);
        url += "&E_DATE=" + $c.stf.getObjectValue(edt_EDate);
        dts_List_3.DataID = encodeURI(url);
        dts_List_3.Reset();
        $c.cm.ShowWin(grd_List_3);
    } else if (MaxTab_01.getSelectedTabIndex() == 4) {
        var url = "/etn/EtnNewList.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listEtnlosslmtAddReceipt&inputMessageId=ETN_NEWLISTING_LOSSLMT_SEARCH_OUT";
        url += "&ISUR_CD=" + $c.stf.getObjectValue(cmb_ISUR_CD);
        url += "&ISU_CD=" + $c.stf.getObjectValue(txb_ISU_CD);
        url += "&S_DATE=" + $c.stf.getObjectValue(edt_SDate);
        url += "&E_DATE=" + $c.stf.getObjectValue(edt_EDate);
        dts_List_4.DataID = encodeURI(url);
        dts_List_4.Reset();
        $c.cm.ShowWin(grd_List_4);
    }
};
scwin.fn_setBzProcsNo = function(obj, dtsObj) {
    scwin.clickBzProcsNo = dtsObj.getCellData(eval(obj), "BZ_PROCS_NO");
};
scwin.fn_OpenNewWin = async function(row, dtsObj) {
    scwin.fn_setBzProcsNo(row, dtsObj);
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        await $c.frame.CreateDialogFrame("ETN_NLIST", "/etn/ULDSTF08012.gfm", "종목상세화면-신규상장", 10, 10, 1100, 960, "window");
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        await $c.frame.CreateDialogFrame("ETN_NLIST", "/etn/ULDSTF08014.gfm", "종목상세화면-추가상장", 10, 10, 1092, 902, "window");
    } else if (MaxTab_01.getSelectedTabIndex() == 3) {
        await $c.frame.CreateDialogFrame("ETN_LNLIST", "/etn/ULDSTF08112.gfm", "종목상세화면(손실제한)-신규상장", 10, 10, 1120, 980, "window");
    } else if (MaxTab_01.getSelectedTabIndex() == 4) {
        await $c.frame.CreateDialogFrame("ETN_LALIST", "/etn/ULDSTF08114.gfm", "종목상세화면(손실제한)-추가상장", 10, 10, 1120, 912, "window");
    }
};
scwin.fn_getDataSet = function() {
    var dtsObj;
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        dtsObj = dts_List_1;
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        dtsObj = dts_List_2;
    } else if (MaxTab_01.getSelectedTabIndex() == 3) {
        dtsObj = dts_List_3;
    } else if (MaxTab_01.getSelectedTabIndex() == 4) {
        dtsObj = dts_List_4;
    }
    return dtsObj;
};


/********************************************** 
 * 함수명   : fn_ExcelDown()
 * 설명       : 정보를 excel로 다운 받는다.
 ***********************************************/
scwin.fn_ExcelDown = function() {
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        $c.data.downloadGridViewExcel(grd_List_1, "신규상장목록(일반)", "", "8");
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        $c.data.downloadGridViewExcel(grd_List_2, "추가상장목록(일반)", "", "8");
    } else if (MaxTab_01.getSelectedTabIndex() == 3) {
        $c.data.downloadGridViewExcel(grd_List_3, "신규상장목록(손실제한)", "", "8");
    } else if (MaxTab_01.getSelectedTabIndex() == 4) {
        $c.data.downloadGridViewExcel(grd_List_4, "추가상장목록(손실제한)", "", "8");
    }
};
scwin.cmb_ISUR_CD_OnSelChange = function() {
    //발행회사 조회시 초기에 재조회 안타게 하기 위함
    if (scwin.vListInit == false) {
        scwin.fn_list_sync();
    }
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    scwin.fn_ExcelDown();
};
scwin.grd_List_1_OnHeadCheckClick = function(col, colid, bCheck) {
    $c.win.alert('grd_List.OnHeadCheckClick(' + col + ',' + colid + ',' + bCheck + ')');
    $c.lce.fn_setCheckBox(grd_List_1, dts_List_1, bCheck);
};
scwin.grd_List_2_OnHeadCheckClick = function(col, colid, bCheck) {
    $c.lce.fn_setCheckBox(grd_List_2, dts_List_2, bCheck);
};
scwin.grd_List_3_OnHeadCheckClick = function(col, colid, bCheck) {
    $c.lce.fn_setCheckBox(grd_List_3, dts_List_3, bCheck);
};
scwin.grd_List_4_OnHeadCheckClick = function(col, colid, bCheck) {
    $c.lce.fn_setCheckBox(grd_List_4, dts_List_4, bCheck);
};
scwin.dts_List_1_OnLoadError = function() {
    $c.stf.alert_error(dts_List_1);
};
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_1);
};
scwin.dts_List_2_OnLoadError = function() {
    $c.stf.alert_error(dts_List_2);
};
scwin.dts_List_3_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_3);
};
scwin.dts_List_3_OnLoadError = function() {
    $c.stf.alert_error(dts_List_3);
};
scwin.dts_List_4_OnLoadError = function() {
    $c.stf.alert_error(dts_List_4);
};
scwin.dts_List_4_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_4);
};
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_2);
};
scwin.grd_List_1_OnDblClick = function(row, colid) {
    if (colid == 'ISU_ABBRV') {
        scwin.fn_OpenNewWin(row, dts_List_1);
    }
};
scwin.grd_List_2_OnDblClick = function(row, colid) {
    if (colid == 'ISU_ABBRV') {
        scwin.fn_OpenNewWin(row, dts_List_2);
    }
};
scwin.grd_List_3_OnDblClick = function(row, colid) {
    if (colid == 'ISU_ABBRV') {
        scwin.fn_OpenNewWin(row, dts_List_3);
    }
};
scwin.grd_List_4_OnDblClick = function(row, colid) {
    if (colid == 'ISU_ABBRV') {
        scwin.fn_OpenNewWin(row, dts_List_4);
    }
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", scwin.procJob));
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001", scwin.procJob));
    //fn_list_sync();

};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.MaxTab_01_OnSelChanged = function(nIndex) {
    scwin.fn_list_sync();
};
scwin.gform_onload = function() {
    $c.pre_newlisting.fn_initSearchDate(edt_SDate, edt_EDate);
    var usrCBData = "1주일전^1,1개월전^2,3개월전^3,6개월전^4,1년전^5,2년전^6";
    cmb_PeriodTp.CBData = usrCBData; //사용자CBData 지정

    //MaxTab_01.ActiveIndex = 1;
    scwin.fn_set_code();
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    scwin.fn_list_sync();
};
scwin.txb_ISU_CD_onblur = function() {
    if (txb_ISU_CD.getValue() == "") {
        txb_ISU_NM.setValue("");
    }
};
scwin.img_IsuSearch_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsur;
    scwin.fn_SetPar = fn_SetParIsur;
    $c.lce.fn_PopFindIsuAll(scwin.fr_SecuGrpId); //상장비상장종목조회

};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.btn_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
